# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">3. ÜNİTE: PEYGAMBERİMİZİN HİCRET SONRASI HAYATI (حَيَاةُ النَّبِيِّ بَعْدَ الْهِجْرَةِ)</text>\n  <rect x="20" y="45" width="210" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Medine\'ye Hicret</text>\n  <text x="125" y="90" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">الْهِجْرَةُ النَّبَوِيَّةُ إِلَى الْمَدِينَةِ</text>\n  <text x="32" y="114" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">الْمُهَاجِرُونَ :</tspan> Muhacirler</text>\n  <text x="32" y="134" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">الْأَنْصَارُ :</tspan> Ensar (Yardımcılar)</text>\n  <text x="32" y="154" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">يَثْرِبُ / الْمَدِينَةُ الْمُنَوَّرَةُ :</tspan></text>\n  <text x="40" y="170" font-size="10" fill="#1e3a8a">Yesrib → Medine-i Münevvere</text>\n  <text x="32" y="192" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">مَسْجِدُ قُبَاءٍ :</tspan> Kuba Mescidi</text>\n  <text x="40" y="208" font-size="10" fill="#1e3a8a">(İslam\'da inşa edilen ilk mescit)</text>\n  <rect x="245" y="45" width="210" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Mescid-i Nebevî ve Suffe</text>\n  <text x="350" y="90" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">بِنَاءُ الْمَسْجِدِ النَّبَوِيِّ وَالصُّفَّةُ</text>\n  <text x="257" y="114" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">النَّاقَةُ (الْقَصْوَاءُ) :</tspan> Devenin</text>\n  <text x="265" y="130" font-size="10" fill="#14532d">çöktüğü arsa (Sehl ve Süheyl).</text>\n  <text x="257" y="150" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">أَبُو أَيُّوبَ الْأَنْصَارِيُّ :</tspan></text>\n  <text x="265" y="166" font-size="10" fill="#14532d">Hz. Peygamber\'i misafir eden sahabi.</text>\n  <text x="257" y="188" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">أَصْحَابُ الصُّفَّةِ :</tspan> Ashâb-ı Suffe</text>\n  <text x="265" y="204" font-size="10" fill="#14532d">(Mescitteki ilk İslam okulu/yatılı eğitim)</text>\n  <rect x="470" y="45" width="210" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Muâhât ve Medine Vesikası</text>\n  <text x="575" y="90" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">الْمُؤَاخَاةُ وَوَثِيقَةُ الْمَدِينَةِ</text>\n  <text x="482" y="114" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">الْمُؤَاخَاةُ :</tspan> Ensar ile Muhacir</text>\n  <text x="490" y="130" font-size="10" fill="#78350f">arasında kurulan kardeşlik akdi.</text>\n  <text x="482" y="152" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">وَثِيقَةُ الْمَدِينَةِ (الصَّحِيفَةُ) :</tspan></text>\n  <text x="490" y="168" font-size="10" fill="#78350f">Medine Sözleşmesi / Vatandaşlık</text>\n  <text x="490" y="184" font-size="10" fill="#78350f">ve birlikte yaşama anayasası.</text>\n  <text x="482" y="206" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">التَّعَايُشُ السِّلْمِيُّ :</tspan> Barış içinde yaşam.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HİCRET SONRASI METİNLERİNDE GEÇEN SÜLÂSÎ MEZÎD FİİL KALIPLARI</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">Bir Harf Eklenenler (Rübâî)</text>\n  <text x="32" y="94" font-size="10.5" font-weight="bold" fill="#1d4ed8">1. İf\'âl Bâbı (أَفْعَلَ - يُفْعِلُ):</text>\n  <text x="40" y="112" font-size="10.5" fill="#1e3a8a">• أَكْرَمَ (İkram etti), أَسْلَمَ (Teslim oldu)</text>\n  <text x="40" y="128" font-size="10.5" fill="#1e3a8a">• أَخْرَجَ (Çıkardı), أَنْفَقَ (İnfak etti)</text>\n  <text x="32" y="152" font-size="10.5" font-weight="bold" fill="#1d4ed8">2. Tef\'îl Bâbı (فَعَّلَ - يُفَعِّلُ):</text>\n  <text x="40" y="170" font-size="10.5" fill="#1e3a8a">• عَلَّمَ (Öğretti), أَسَّسَ (Kurdu/İnşa etti)</text>\n  <text x="32" y="194" font-size="10.5" font-weight="bold" fill="#1d4ed8">3. Müfâale Bâbı (فَاعَلَ - يُفَاعِلُ):</text>\n  <text x="40" y="212" font-size="10.5" fill="#1e3a8a">• هَاجَرَ (Hicret etti), آخَى (Kardeş yaptı)</text>\n  <text x="40" y="228" font-size="10.5" fill="#1e3a8a">• شَارَكَ (Katıldı / Ortak oldu)</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">İki Harf Eklenenler (Humâsî)</text>\n  <text x="257" y="94" font-size="10.5" font-weight="bold" fill="#15803d">1. İftî\'âl Bâbı (اِفْتَعَلَ - يَفْتَعِلُ):</text>\n  <text x="265" y="112" font-size="10.5" fill="#14532d">• اِجْتَمَعَ (Toplandı), اِشْتَرَى (Satın aldı)</text>\n  <text x="265" y="128" font-size="10.5" fill="#14532d">• اِتَّخَذَ (Edindi)</text>\n  <text x="257" y="152" font-size="10.5" font-weight="bold" fill="#15803d">2. Tefe\'\'ul Bâbı (تَفَعَّلَ - يَتَفَعَّلُ):</text>\n  <text x="265" y="170" font-size="10.5" fill="#14532d">• تَعَلَّمَ (Öğrendi), تَحَدَّثَ (Konuştu)</text>\n  <text x="257" y="194" font-size="10.5" font-weight="bold" fill="#15803d">3. Tefâ\'ul Bâbı (تَفَاعَلَ - يَتَفَاعَلُ):</text>\n  <text x="265" y="212" font-size="10.5" fill="#14532d">• تَعَاوَنَ (Yardımlaştı), تَآخَى (Kardeş oldu)</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">Üç Harf Eklenenler (Südâsî)</text>\n  <text x="482" y="94" font-size="10.5" font-weight="bold" fill="#7e22ce">• İstif\'âl Bâbı (اِسْتَفْعَلَ - يَسْتَفْعِلُ):</text>\n  <text x="490" y="114" font-size="10.5" fill="#581c87">Başına (ا س ت) harfleri eklenir.</text>\n  <text x="490" y="136" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">اِسْتَقْبَلَ :</tspan> Karşıladı</text>\n  <text x="498" y="152" font-size="10" fill="#581c87">(اِسْتَقْبَلَ الْأَنْصَارُ النَّبِيَّ بـِالْفَرَحِ)</text>\n  <text x="490" y="176" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">اِسْتَقَرَّ :</tspan> Yerleşti, istikrar buldu</text>\n  <text x="490" y="198" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">اِسْتَشَارَ :</tspan> İstişare etti, danıştı</text>\n  <text x="490" y="220" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">اِسْتَغْفَرَ :</tspan> Bağışlanma diledi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MESCİD-İ NEBEVÎ\'NİN İŞLEVLERİ VE ÖRNEK ARAPÇA CÜMLELER</text>\n  <rect x="20" y="45" width="660" height="195" rx="10" fill="#ffffff" stroke="#94a3b8" stroke-width="1.8"/>\n  <rect x="35" y="60" width="630" height="38" rx="6" fill="#eff6ff" stroke="#93c5fd"/>\n  <text x="350" y="83" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">1. هَاجَرَ الرَّسُولُ ﷺ مِنْ مَكَّةَ إِلَى الْمَدِينَةِ ، وَاسْتَقْبَلَهُ الْأَنْصَارُ بِالْفَرَحِ وَالسُّرُورِ.</text>\n  <text x="350" y="112" text-anchor="middle" font-size="10.5" fill="#334155">(Resulullah Mekke\'den Medine\'ye hicret etti ve Ensar onu sevinç ve neşeyle karşıladı.)</text>\n  <rect x="35" y="124" width="630" height="38" rx="6" fill="#f0fdf4" stroke="#86efac"/>\n  <text x="350" y="147" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">2. بَنَى النَّبِيُّ ﷺ الْمَسْجِدَ النَّبَوِيَّ وَشَارَكَ الصَّحَابَةَ فِي الْبِنَاءِ بِنَفْسِهِ.</text>\n  <text x="350" y="176" text-anchor="middle" font-size="10.5" fill="#334155">(Hz. Peygamber Mescid-i Nebevî\'yi inşa etti ve inşaatta bizzat sahabeye katıldı.)</text>\n  <rect x="35" y="188" width="630" height="38" rx="6" fill="#fef3c7" stroke="#fcd34d"/>\n  <text x="350" y="211" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">3. آخَى الرَّسُولُ ﷺ بَيْنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ ، وَأَسَّسَ الصُّفَّةَ لِلتَّعْلِيمِ.</text>\n  <text x="350" y="236" text-anchor="middle" font-size="10.5" fill="#334155">(Resulullah Muhacirler ile Ensar\'ı kardeş ilan etti ve eğitim için Suffe\'yi kurdu.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
